<?php require 'partials.php';$token=preg_replace('/[^a-f0-9]/','',$_GET['token']??'');$s=db()->prepare('SELECT p.*,g.music_theme,q.title FROM players p JOIN games g ON g.id=p.game_id JOIN quizzes q ON q.id=g.quiz_id WHERE p.token=?');$s->bind_param('s',$token);$s->execute();$p=$s->get_result()->fetch_assoc();if(!$p)redirect('index.php');page_top('Jolta');?>
<section class="live-shell player" data-game="<?=$p['game_id']?>"><header class="live-top"><span><?=e($p['avatar'])?> <?=e($p['name'])?></span><strong id="myScore"><?=$p['score']?> p</strong></header><div id="playerStage" class="player-stage"><div class="waiting"><b>⚡</b><h1>Du är med!</h1><p>Vänta på att värden startar.</p></div></div></section><script>window.JOLT={gameId:<?=$p['game_id']?>,token:'<?=e($token)?>',role:'player'}</script><script src="assets/live.js"></script><?php page_bottom();?>
